import { useState } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const UploadForm = ({ onUploadSuccess }) => {
  const [file, setFile] = useState(null);
  const { user } = useAuth();

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!file) {
      alert('Please select a file.');
      return;
    }

    const formData = new FormData();
    formData.append('image', file);

    try {
      await axios.post('/api/gallery/upload', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: `Bearer ${user.token}`
        }
      });

      alert('Image uploaded successfully!');
      setFile(null);
      onUploadSuccess(); // ✅ Gallery ko refresh karo
    } catch (error) {
      alert(error.response?.data?.message || 'Error uploading image');
    }
  };

  return (
    <form onSubmit={handleSubmit} className="mb-4">
      <div className="mb-3">
        <input 
          type="file" 
          accept="image/*" 
          onChange={handleFileChange} 
          className="form-control"
          required 
        />
      </div>
      <button type="submit" className="btn btn-success">Upload Image</button>
    </form>
  );
};

export default UploadForm;
